import { COURSES } from './curriculum.mjs';
import { courseAccess } from './progression.mjs';
import { BRANCH_CONSTELLATIONS, TERM_CONSTELLATIONS, projectConstellation, placeCourses } from './sky-layout.mjs';
import { courseRelationships, CONNECTION_TYPES } from './connections.mjs';
import { skyAccent } from './sky-palette.mjs';

export const COURSE_SECTIONS = [
 { numeral:'I', title:'Course description', note:'The official course description will appear here when the course files are added.' },
 { numeral:'II', title:'Topic rundown', note:'The topic list will appear here when the course files are added.' },
 { numeral:'III', title:'Skills for the future', note:'Important topics and skills for later courses will appear here when the course files are added.' },
 { numeral:'IV', title:'Mastery quiz', note:'The mastery quiz will be added after you provide the quiz files.' }
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function courseSky(c){
 const chart=projectConstellation(c.specialization?BRANCH_CONSTELLATIONS[c.specialization]:TERM_CONSTELLATIONS[c.term],{x:55,y:45,width:390,height:370});
 const group=COURSES.filter(n=>c.specialization?n.specialization===c.specialization:!n.specialization&&n.term===c.term);
 const anchor=chart.vertices[placeCourses(chart,group)[c.id].anchorIndex];
 return `<div class="dossier-sky" style="${skyAccent(chart.id)}" aria-hidden="true"><svg viewBox="0 0 500 460"><g class="dossier-trails">${chart.paths.map(path=>`<polyline points="${path.map(i=>`${chart.vertices[i].x},${chart.vertices[i].y}`).join(' ')}"/>`).join('')}</g><g class="dossier-stars">${chart.vertices.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="${p.degree>2?3.5:2.5}"/>`).join('')}</g><g class="dossier-focus" transform="translate(${anchor.x} ${anchor.y})"><path d="M0 -30L5 -5L30 0L5 5L0 30L-5 5L-30 0L-5 -5Z"/><circle r="4"/></g></svg><span>${chart.name}</span></div>`;
}

export function renderCoursePanel(progress,c,{preview=false,section=0,reward=null}={}){
 const current=COURSE_SECTIONS[section],access=courseAccess(progress,c.id,{preview}),record=progress.academicRecords[c.id];
 const links=courseRelationships(COURSES,c.id);
 const met=(id,type)=>type==='H'?progress.academicRecords[id]?.status==='COMPLETED':['ACTIVE','COMPLETED'].includes(progress.academicRecords[id]?.status);
 const relationshipRows=(rows,{incoming=false}={})=>rows.map(({course:other,type})=>`<div class="dossier-prereq dossier-relation ${incoming&&met(other.id,type)?'is-met':''}" data-related-course="${other.id}" data-relation-type="${type}"><span class="relation-type" title="${CONNECTION_TYPES[type]}">${type}</span><button data-course-link="${other.id}"><strong>${other.id}</strong><span>${esc(other.title)}</span>${other.specialization?'<small>'+other.specialization+' specialization</small>':''}</button><span class="relation-arrow" aria-hidden="true">${incoming&&met(other.id,type)?'✓':'↗'}</span></div>`).join('');
 const relationships=`<section class="dossier-connections" aria-label="Course prerequisites"><h4>Prerequisites</h4>${links.prerequisites.length?relationshipRows(links.prerequisites,{incoming:true}):'<p>No course prerequisites.</p>'}</section><section class="dossier-connections" aria-label="Courses that require this course"><h4>Prerequisite for</h4>${links.leadsTo.length?relationshipRows(links.leadsTo):'<p>No downstream prerequisite courses in this curriculum.</p>'}</section><section class="dossier-connections" aria-label="Co-requisite courses"><h4>Co-requisite with</h4>${links.corequisites.length?relationshipRows(links.corequisites):'<p>No co-requisite courses.</p>'}</section><dl class="dossier-key"><div><dt>H</dt><dd>Hard prerequisite</dd></div><div><dt>S</dt><dd>Soft prerequisite</dd></div><div><dt>C</dt><dd>Co-requisite</dd></div></dl>`;
 const status=preview?'Preview only':record?.status==='COMPLETED'?'Academically completed':record?.status==='ACTIVE'?'Course active':access.allowed?'Ready to activate':'Not yet available';

 const celebration=!preview&&reward?.id===c.id;
 const rewardMarkup=celebration?`<div class="completion-reward" role="status"><span class="reward-star" aria-hidden="true">✦</span><div><h4>${reward.termComplete?'Term '+reward.term+' constellation complete':'A new star in your sky'}</h4><p>${reward.academic.complete} / ${reward.academic.total} academic courses complete${reward.newlyAvailable.length?' · '+reward.newlyAvailable.length+' now ready to activate':''}</p></div></div><button class="secondary reward-return" data-action="close-inspector">Return to the sky ↗</button>`:'';
 const action=celebration?rewardMarkup:preview?`<p class="dossier-readonly">Preview only · Academic records stay unchanged.</p>`:record?.status==='COMPLETED'?'<p class="dossier-readonly">Academic completion recorded by you. Mastery is assessed separately.</p>':`<button class="primary dossier-academic" data-academic="${record?.status==='ACTIVE'?'COMPLETED':'ACTIVE'}" ${access.allowed?'':'disabled'}>${record?.status==='ACTIVE'?'Record academic completion':'Activate course'}</button><p class="dossier-reason">${esc(access.reason)}</p>`;
 return `<div class="dossier-layout ${celebration?'is-celebrating':''}"><button class="dossier-close" data-action="close-inspector" aria-label="Close course details" autofocus>×</button><div class="dossier-identity"><span class="dossier-path">${c.specialization||'SHARED CIVIL ENGINEERING'}</span>${courseSky(c)}<div class="dossier-heading"><span class="course-code">${c.id}</span><h2 id="dossier-title">${esc(c.title)}</h2><div class="course-meta"><span>Year ${c.year}</span><span>Term ${c.term}</span><span>${c.units} unit${c.units!==1?'s':''}</span></div><span class="course-status ${preview?'preview-status':''}">${status}</span></div></div><div class="dossier-tabs" role="tablist" aria-label="Course sections"><span class="dossier-thread" aria-hidden="true"></span>${COURSE_SECTIONS.map((s,i)=>`<button id="course-tab-${i}" class="dossier-tab" role="tab" aria-selected="${i===section}" aria-controls="course-section" tabindex="${i===section?0:-1}" data-course-section="${i}" aria-label="${s.numeral}: ${s.title}" title="${s.title}"><span class="dossier-diamond" aria-hidden="true"></span><span class="dossier-numeral">${s.numeral}</span><span class="dossier-tab-name">${s.title}</span></button>`).join('')}</div><div class="dossier-reading"><header class="dossier-section-heading"><span aria-hidden="true">${current.numeral}</span><h3>${current.title}</h3></header><div class="dossier-scroll"><section id="course-section" role="tabpanel" aria-labelledby="course-tab-${section}" tabindex="0"><div class="dossier-placeholder"><span class="dossier-small-star" aria-hidden="true">✦</span><h4>${section===3?'Quiz coming later':'Awaiting course files'}</h4><p>${current.note}</p>${section===3?'<button class="secondary" disabled>Mastery quiz · Coming later</button>':''}</div></section>${relationships}</div><footer class="dossier-footer">${action}<p class="dossier-mastery-scope">${c.requiredMastery?'Required Normal Mode mastery node.':'Academic requirement · Mastery not required.'}</p></footer></div></div>`;
}
